    public sealed class TypedSubscriptionBuilder
    {
        private readonly IDbConnection conn;
        private Action<SubscriptionEventContext>? Applied;
        private Action<ErrorContext, Exception>? Error;
        private readonly List<string> querySqls = new();

        internal TypedSubscriptionBuilder(IDbConnection conn, Action<SubscriptionEventContext>? applied, Action<ErrorContext, Exception>? error)
        {
            this.conn = conn;
            Applied = applied;
            Error = error;
        }

        public TypedSubscriptionBuilder OnApplied(Action<SubscriptionEventContext> callback)
        {
            Applied += callback;
            return this;
        }

        public TypedSubscriptionBuilder OnError(Action<ErrorContext, Exception> callback)
        {
            Error += callback;
            return this;
        }

        public TypedSubscriptionBuilder AddQuery<TRow>(Func<QueryBuilder, global::SpacetimeDB.IQuery<TRow>> build)
        {
            var qb = new QueryBuilder();
            querySqls.Add(build(qb).ToSql());
            return this;
        }

        public SubscriptionHandle Subscribe() => new(conn, Applied, Error, querySqls.ToArray());
    }

    public abstract partial class Reducer
    {
        private Reducer() { }
    }

    public abstract partial class Procedure
    {
        private Procedure() { }
    }

    public sealed class DbConnection : DbConnectionBase<DbConnection, RemoteTables, Reducer>
    {
        public override RemoteTables Db { get; }
        public readonly RemoteReducers Reducers;
        public readonly RemoteProcedures Procedures;

        public DbConnection()
        {
            Db = new(this);
            Reducers = new(this);
            Procedures = new(this);
        }

        protected override IEventContext ToEventContext(Event<Reducer> Event) =>
        new EventContext(this, Event);

        protected override IReducerEventContext ToReducerEventContext(ReducerEvent<Reducer> reducerEvent) =>
        new ReducerEventContext(this, reducerEvent);

        protected override ISubscriptionEventContext MakeSubscriptionEventContext() =>
        new SubscriptionEventContext(this);

        protected override IErrorContext ToErrorContext(Exception exception) =>
        new ErrorContext(this, exception);

        protected override IProcedureEventContext ToProcedureEventContext(ProcedureEvent procedureEvent) =>
        new ProcedureEventContext(this, procedureEvent);

        protected override bool Dispatch(IReducerEventContext context, Reducer reducer)
        {
            var eventContext = (ReducerEventContext)context;
            return reducer switch
            {
                Reducer.AcceptIdentityLink args => Reducers.InvokeAcceptIdentityLink(eventContext, args),
                Reducer.ActivateInventoryHotbar args => Reducers.InvokeActivateInventoryHotbar(eventContext, args),
                Reducer.ApplySystemMap args => Reducers.InvokeApplySystemMap(eventContext, args),
                Reducer.AssignInventoryHotbar args => Reducers.InvokeAssignInventoryHotbar(eventContext, args),
                Reducer.BeginAuthoredFlightReview args => Reducers.InvokeBeginAuthoredFlightReview(eventContext, args),
                Reducer.BeginConstructionTraversal args => Reducers.InvokeBeginConstructionTraversal(eventContext, args),
                Reducer.BindGameSession args => Reducers.InvokeBindGameSession(eventContext, args),
                Reducer.BoardShipPassenger args => Reducers.InvokeBoardShipPassenger(eventContext, args),
                Reducer.CancelConstructionTraversal args => Reducers.InvokeCancelConstructionTraversal(eventContext, args),
                Reducer.ChangeShipFlightFitting args => Reducers.InvokeChangeShipFlightFitting(eventContext, args),
                Reducer.ClaimCharacterArmory args => Reducers.InvokeClaimCharacterArmory(eventContext, args),
                Reducer.ClaimInputControl args => Reducers.InvokeClaimInputControl(eventContext, args),
                Reducer.ClaimStarterKit args => Reducers.InvokeClaimStarterKit(eventContext, args),
                Reducer.DiscardDefinitionDraft args => Reducers.InvokeDiscardDefinitionDraft(eventContext, args),
                Reducer.DropInventoryItem args => Reducers.InvokeDropInventoryItem(eventContext, args),
                Reducer.EditShipFurnishing args => Reducers.InvokeEditShipFurnishing(eventContext, args),
                Reducer.EnterAuthoredPilot args => Reducers.InvokeEnterAuthoredPilot(eventContext, args),
                Reducer.EnterConstructionReview args => Reducers.InvokeEnterConstructionReview(eventContext, args),
                Reducer.EnterLab args => Reducers.InvokeEnterLab(eventContext, args),
                Reducer.EquipInventoryItem args => Reducers.InvokeEquipInventoryItem(eventContext, args),
                Reducer.EvaCycleAirlock args => Reducers.InvokeEvaCycleAirlock(eventContext, args),
                Reducer.EvaEmergencyReturn args => Reducers.InvokeEvaEmergencyReturn(eventContext, args),
